from typing import List


def separate_paren_groups(paren_string: str) -> List[str]:
    # Step 1: Remove spaces from the input string
    paren_string = paren_string.replace(" ", "")

    # Step 2: Iterate through the input string and identify the start and end indices of each group of nested parentheses
    groups = []
    start = 0
    count = 0
    for i, char in enumerate(paren_string):
        if char == '(':
            count += 1
            if count == 1:
                start = i
        elif char == ')':
            count -= 1
            if count == 0:
                groups.append(paren_string[start:i+1])

    # Step 4: Return the extracted groups as a list
    return groups

